from itertools import permutations
sides=["S","M","P","R"]
ans=set()
for p in permutations(sides):
    if p[0]!="S": continue
    nxt={p[i]:p[(i+1)%4] for i in range(4)}
    if nxt["S"]=="M" and nxt["P"]=="R":
        ans.add(p[(p.index("M")+2)%4])
opts={"A":"C","B":"R","C":"S","D":"P"}
assert ans=={opts["B"]}
for k in "ACD": assert opts[k] not in ans

expr="18 - 23 * 455 / 7 + 28"
def swap(e,a,b):
    return "".join(b if ch==a else a if ch==b else ch for ch in e)
opts={"A":("/","-"),"B":("-","+"),"C":("+","*"),"D":("-","*")}
res={k:eval(swap(expr,*v)) for k,v in opts.items()}
fit=[k for k,v in res.items() if abs(v-377)<1e-9]
assert fit==["D"]

s="L M B A _ H O L M B A C _ O L M _ A C H O L _ B A C H O L _".split()
opts={"A":"CHMBM","B":"CMHBM","C":"CHBMM","D":"CHMMB"}
def ok(fill):
    it=iter(fill); t=[next(it) if c=="_" else c for c in s]
    return all(t[i]=="LMBACHO"[i%7] for i in range(len(t)))
fit=[k for k,v in opts.items() if ok(v)]
assert fit==["C"]

# derive: Q father of L; L sibling of R -> Q parent of R; Q male (husband of P)
facts={"wife":[("P","Q"),("R","K")],"father":[("Q","L")],"sister":[("L","R")]}
parent={}
for f,c in facts["father"]: parent.setdefault(c,set()).add(f)
for a,b in facts["sister"]: parent.setdefault(b,set()).update(parent.get(a,set()))
male={h for w,h in facts["wife"]}
rel="Father" if "Q" in parent.get("R",set()) and "Q" in male else None
opts={"A":"Sister","B":"Mother","C":"Father","D":"Wife"}
assert rel==opts["C"]
for k in "ABD": assert rel!=opts[k]
